--eg_account_assist_balance with origin as( select id,contract_code ,org_id ,account_code, bill_contract_code,currency_code ,month_debit_amount,month_credit_amount,eaab.year_begin_debit_balance,eaab.year_begin_credit_balance ,eaab.year_debit_amount,eaab.year_credit_amount,eaab.month_begin_debit_balance, eaab.month_begin_credit_balance ,eaab.month_end_debit_balance, eaab.month_end_credit_balance from eg_account_assist_balance eaab where 1=1
and eaab.period_code >= #{param.periodCodeStart}
and eaab.period_code <= #{param.periodCodeEnd}
and contract_code in
#{item}
and org_id = #{param.orgId}
and org_id in
#{item}
) ,exceptFiltered as ( SELECT id,contract_code ,org_id ,account_code, bill_contract_code,currency_code, month_debit_amount,month_credit_amount,year_begin_debit_balance,year_begin_credit_balance, year_debit_amount,year_credit_amount,month_begin_debit_balance,month_begin_credit_balance, month_end_debit_balance, month_end_credit_balance FROM ( SELECT id,contract_code ,org_id ,account_code, bill_contract_code,currency_code ,month_debit_amount,month_credit_amount,year_begin_debit_balance,year_begin_credit_balance ,year_debit_amount,year_credit_amount,month_begin_debit_balance,month_begin_credit_balance ,month_end_debit_balance,month_end_credit_balance,
COUNT(*) FILTER (WHERE month_debit_amount !=0 or month_credit_amount !=0) OVER (PARTITION BY contract_code ,org_id ,account_code, bill_contract_code,currency_code) AS cond1,
COUNT(*) FILTER (WHERE month_debit_amount !=0 or month_credit_amount !=0 or month_end_debit_balance!=0 or month_end_credit_balance!=0) OVER (PARTITION BY contract_code ,org_id ,account_code, bill_contract_code,currency_code) AS cond2,
COUNT(*) FILTER (WHERE month_end_debit_balance!=0 or month_end_credit_balance!=0) OVER (PARTITION BY contract_code ,org_id ,account_code, bill_contract_code,currency_code) AS cond3,
COUNT(*) FILTER (WHERE year_debit_amount !=0 or year_credit_amount !=0 ) OVER (PARTITION BY contract_code ,org_id ,account_code, bill_contract_code,currency_code) AS cond4,
COUNT(*) FILTER (WHERE month_end_debit_balance!=0 or month_end_credit_balance!=0 or year_debit_amount !=0 or year_credit_amount !=0 ) OVER (PARTITION BY contract_code ,org_id ,account_code, bill_contract_code,currency_code) AS cond5,
COUNT(*) OVER (PARTITION BY contract_code ,org_id ,account_code, bill_contract_code,currency_code) AS cond0,
COUNT(*) OVER (PARTITION BY contract_code ,org_id ,account_code, bill_contract_code,currency_code) AS total_rows FROM origin ) subquery WHERE 1=1
and cond1 = total_rows
and cond2 = total_rows
and cond3 = total_rows
and cond4 = total_rows
and cond5 = total_rows
and cond0 = total_rows
) , sub_account as ( select contract_code ,org_id ,account_code, bill_contract_code,min(id) min_id,max(id) max_id,currency_code from exceptFiltered group by contract_code ,org_id ,account_code ,bill_contract_code,currency_code ) ,sumtab as( select eaab.contract_code ,eaab.org_id ,eaab.account_code , eaab.bill_contract_code,eaab.currency_code, sum(eaab.month_debit_amount) month_debit_amount, sum(eaab.month_credit_amount) month_credit_amount from eg_account_assist_balance eaab join sub_account on eaab.contract_code = sub_account.contract_code and eaab.org_id = sub_account.org_id and eaab.account_code = sub_account.account_code and COALESCE(eaab.bill_contract_code,'') =COALESCE(sub_account.bill_contract_code,'') and eaab.currency_code = sub_account.currency_code and eaab.id >= sub_account.min_id and eaab.id <= sub_account.max_id group by eaab.contract_code ,eaab.org_id ,eaab.account_code ,eaab.bill_contract_code,eaab.currency_code) ,mintab as( select eaab.contract_code ,eaab.org_id ,eaab.account_code , eaab.bill_contract_code, eaab.currency_code,eaab.year_begin_debit_balance,eaab.year_begin_credit_balance, eaab.year_debit_amount,eaab.year_credit_amount,eaab.month_begin_debit_balance, eaab.month_begin_credit_balance from eg_account_assist_balance eaab join sub_account on eaab.contract_code = sub_account.contract_code and eaab.org_id = sub_account.org_id and eaab.account_code = sub_account.account_code and COALESCE(eaab.bill_contract_code,'') =COALESCE(sub_account.bill_contract_code,'') and eaab.currency_code = sub_account.currency_code and eaab.id =sub_account.min_id ) ,maxtab as( select eaab.contract_code ,eaab.org_id ,eaab.account_code , eaab.bill_contract_code, eaab.currency_code,eaab.year_begin_debit_balance,eaab.year_begin_credit_balance, eaab.year_debit_amount,eaab.year_credit_amount,eaab.month_end_debit_balance, eaab.month_end_credit_balance from eg_account_assist_balance eaab join sub_account on eaab.contract_code = sub_account.contract_code and eaab.org_id = sub_account.org_id and eaab.account_code = sub_account.account_code and COALESCE(eaab.bill_contract_code,'') =COALESCE(sub_account.bill_contract_code,'') and eaab.currency_code = sub_account.currency_code and eaab.id =sub_account.max_id ) ,res_account as ( select sumtab.contract_code ,sumtab.org_id ,sumtab.account_code ,sumtab.bill_contract_code,sumtab.currency_code,mintab.month_begin_debit_balance, mintab.month_begin_credit_balance, sumtab.month_debit_amount,sumtab.month_credit_amount,mintab.year_begin_debit_balance, mintab.year_begin_credit_balance,maxtab.year_debit_amount,maxtab.year_credit_amount,maxtab.month_end_debit_balance,maxtab.month_end_credit_balance from sumtab join mintab on sumtab.contract_code = mintab.contract_code and sumtab.org_id = mintab.org_id and sumtab.account_code = mintab.account_code and COALESCE(sumtab.bill_contract_code,'') =COALESCE(mintab.bill_contract_code,'') and sumtab.currency_code = mintab.currency_code join maxtab on sumtab.contract_code = maxtab.contract_code and sumtab.org_id = maxtab.org_id and sumtab.account_code = maxtab.account_code and COALESCE(sumtab.bill_contract_code,'') =COALESCE(maxtab.bill_contract_code,'') and sumtab.currency_code = maxtab.currency_code) --eg_voucher ,ev_eve as ( select ev.id voucher_id,ev.contract_code ,ev.org_id ,eve.account_code, eve.bill_contract_code,eve.id,ev.currency,eve.debit_amount,eve.credit_amount from eg_voucher ev join eg_voucher_entry eve on ev.id = eve.voucher_id where 1=1
and ev.period_code =#{param.periodCodeEnd} and eve.period_code =#{param.periodCodeEnd}
and ev.contract_code in
#{item}
and ev.org_id = #{param.orgId}
and ev.org_id in
#{item}
) ,sub_ev as ( select string_agg(ev_eve.voucher_id::text, ',') voucher_id,ev_eve.contract_code ,ev_eve.org_id ,ev_eve.account_code, ev_eve.bill_contract_code,ev_eve.currency,min(ev_eve.id) min_id,max(ev_eve.id) max_id from ev_eve group by ev_eve.contract_code ,ev_eve.org_id ,ev_eve.account_code ,ev_eve.bill_contract_code,ev_eve.currency ) ,res_voucher as( select ev_eve.contract_code ,ev_eve.org_id ,ev_eve.account_code , ev_eve.bill_contract_code,ev_eve.currency currency_code, sum(ev_eve.debit_amount) debit_amount, sum(ev_eve.credit_amount) credit_amount from ev_eve join sub_ev on ev_eve.contract_code = sub_ev.contract_code and ev_eve.org_id = sub_ev.org_id and ev_eve.account_code = sub_ev.account_code and COALESCE(ev_eve.bill_contract_code,'') =COALESCE(sub_ev.bill_contract_code,'') and ev_eve.currency = sub_ev.currency and ev_eve.id >= sub_ev.min_id and ev_eve.id <= sub_ev.max_id group by ev_eve.contract_code ,ev_eve.org_id ,ev_eve.account_code ,ev_eve.bill_contract_code,ev_eve.currency) --eg_manual ,em_emv as ( select emv.contract_code ,em.org_id ,emv.account_code, emv.loans_contract_code,em.currency_code,emv.id,emv.debit_amount,emv.credit_amount,em.period_code from eg_manual em join eg_manual_voucher emv on em.id = emv.manual_id where 1=1
and em.period_code =#{param.periodCodeEnd} and emv.period_code =#{param.periodCodeEnd}
and emv.contract_code in
#{item}
and em.org_id = #{param.orgId}
and em.org_id in
#{item}
) ,sub_em as ( select em_emv.contract_code ,em_emv.org_id ,em_emv.account_code, em_emv.loans_contract_code,em_emv.currency_code,min(em_emv.id) min_id,max(em_emv.id) max_id from em_emv group by em_emv.contract_code ,em_emv.org_id ,em_emv.account_code ,em_emv.loans_contract_code,em_emv.currency_code ) ,res_manual as( select em_emv.contract_code ,em_emv.org_id ,em_emv.account_code , em_emv.loans_contract_code bill_contract_code,em_emv.currency_code, sum(em_emv.debit_amount) debit_amount, sum(em_emv.credit_amount) credit_amount from em_emv join sub_em on em_emv.contract_code = sub_em.contract_code and em_emv.org_id = sub_em.org_id and em_emv.account_code = sub_em.account_code and COALESCE(em_emv.loans_contract_code,'') =COALESCE(sub_em.loans_contract_code,'') and em_emv.currency_code = sub_em.currency_code and em_emv.id >= sub_em.min_id and em_emv.id <= sub_em.max_id group by em_emv.contract_code ,em_emv.org_id ,em_emv.account_code ,em_emv.loans_contract_code,em_emv.currency_code) ,res_all as( select
res_account.currency_code, --币种 res_account.contract_code, --合同编码 res_account.org_id, --签约主体 res_account.account_code, --科目代码 res_account.bill_contract_code, --借款合同编号
res_account.currency_code, --币种 res_account.contract_code, --合同编码 res_account.org_id, --签约主体 res_account.account_code, --科目代码 res_account.bill_contract_code, --借款合同编号
res_voucher.currency_code, --币种 res_voucher.contract_code, --合同编码 res_voucher.org_id, --签约主体 res_voucher.account_code, --科目代码 res_voucher.bill_contract_code, --借款合同编号
res_manual.currency_code, --币种 res_manual.contract_code, --合同编码 res_manual.org_id, --签约主体 res_manual.account_code, --科目代码 res_manual.bill_contract_code, --借款合同编号
COALESCE(res_account.month_begin_debit_balance,0) month_begin_debit_balance, -- 期初借方余额 COALESCE(res_account.month_begin_credit_balance,0) month_begin_credit_balance, -- 期初贷方余额 COALESCE(res_account.year_begin_debit_balance,0) year_begin_debit_balance, -- 年初借方余额 COALESCE(res_account.year_begin_credit_balance,0) year_begin_credit_balance, -- 年初贷方余额 COALESCE(res_account.month_debit_amount,0) + COALESCE(res_voucher.debit_amount,0) + COALESCE(res_manual.debit_amount,0) month_debit_amount, -- 期间借方放生额 COALESCE(res_account.month_credit_amount,0) + COALESCE(res_voucher.credit_amount,0) + COALESCE(res_manual.credit_amount,0) month_credit_amount, --期间贷方发生额 COALESCE(res_account.year_debit_amount,0) + COALESCE(res_voucher.debit_amount,0) + COALESCE(res_manual.debit_amount,0) year_debit_amount, -- 年借方发生额 COALESCE(res_account.year_credit_amount,0) + COALESCE(res_voucher.credit_amount,0) + COALESCE(res_manual.credit_amount,0) year_credit_amount, --年贷方发生额 COALESCE(res_account.month_end_debit_balance,0) + COALESCE(res_voucher.debit_amount,0) + COALESCE(res_manual.debit_amount,0) month_end_debit_balance, --期末借方余额 COALESCE(res_account.month_end_credit_balance,0) + COALESCE(res_voucher.credit_amount,0) + COALESCE(res_manual.credit_amount,0) month_end_credit_balance --期末贷方余额 from res_account
LEFT JOIN res_voucher on 1=1
LEFT JOIN res_voucher on 1=2
RIGHT JOIN res_voucher on 1=2
LEFT JOIN res_voucher on 1=2
LEFT JOIN res_voucher on 1=1
LEFT JOIN res_voucher on 1=2
RIGHT JOIN res_voucher on 1=2
LEFT JOIN res_voucher on 1=1
and res_account.contract_code = res_voucher.contract_code and res_account.org_id = res_voucher.org_id and res_account.account_code = res_voucher.account_code and coalesce(res_account.bill_contract_code,'') = coalesce(res_voucher.bill_contract_code,'') and res_account.currency_code = res_voucher.currency_code
LEFT JOIN res_manual on 1=1
LEFT JOIN res_manual on 1=2
LEFT JOIN res_manual on 1=2
RIGHT JOIN res_manual on 1=2
LEFT JOIN res_manual on 1=2
LEFT JOIN res_manual on 1=1
LEFT JOIN res_manual on 1=1
LEFT JOIN res_manual on 1=1
and res_voucher.contract_code = res_manual.contract_code and res_voucher.org_id = res_manual.org_id and res_voucher.account_code = res_manual.account_code and coalesce(res_voucher.bill_contract_code,'') = coalesce(res_manual.bill_contract_code,'') and res_voucher.currency_code = res_manual.currency_code
and res_account.contract_code = res_manual.contract_code and res_account.org_id = res_manual.org_id and res_account.account_code = res_manual.account_code and coalesce(res_account.bill_contract_code,'') = coalesce(res_manual.bill_contract_code,'') and res_account.currency_code = res_manual.currency_code
), res as( select sub_ev.voucher_id, --凭证编号 ec.id contract_id, --合同表id，用于前端跳转合同详情 ea.account_name, --科目名称 ec.client_code, --客户编号 client.client_name , --客户名称 ec.lease_type, --借贷类型
res_all.currency_code, --币种 res_all.contract_code, --合同编码 res_all.org_id, --签约主体 res_all.account_code, --科目代码 res_all.bill_contract_code, --借款合同编号 res_all.year_begin_debit_balance, -- 年初借方余额 res_all.year_begin_credit_balance, -- 年初贷方余额 res_all.month_begin_debit_balance, -- 期初借方余额 res_all.month_begin_credit_balance, -- 期初贷方余额 res_all.month_debit_amount, -- 期间借方放生额 res_all.month_credit_amount, --期间贷方发生额 res_all.year_debit_amount, -- 年借方发生额 res_all.year_credit_amount, --年贷方发生额 res_all.month_end_debit_balance, --期末借方余额 res_all.month_end_credit_balance --期末贷方余额 from res_all left join eg_contract ec on ec.org_id =res_all.org_id and ec.contract_code =res_all.contract_code left join eg_client client on ec.client_code = client.client_code left join sub_ev on sub_ev.contract_code = res_all.contract_code and sub_ev.org_id = res_all.org_id and sub_ev.account_code = res_all.account_code and COALESCE(sub_ev.bill_contract_code,'') =COALESCE(res_all.bill_contract_code,'') and sub_ev.currency = res_all.currency_code left join (select distinct account_code, account_name from eg_account) ea on res_all.account_code = ea.account_code
where 1=1
and ec.client_name like concat('%', #{param.clientName}::text, '%')
and res_all.account_code >= #{param.accountCodeStart}
and res_all.account_code <= #{param.accountCodeEnd}
and res_all.currency_code = #{param.currencyCode}
and res_all.bill_contract_code = #{param.billContractCode}
and ea.account_name like concat('%', #{param.accountName}::text, '%')
)

--eg_account_assist_balance with origin as( select id,org_id ,account_code,currency_code ,month_debit_amount,month_credit_amount,eaab.year_begin_debit_balance,eaab.year_begin_credit_balance ,eaab.year_debit_amount,eaab.year_credit_amount,eaab.month_begin_debit_balance, eaab.month_begin_credit_balance ,eaab.month_end_debit_balance, eaab.month_end_credit_balance from eg_account_assist_balance eaab where 1=1
and eaab.period_code >= #{param.periodCodeStart}
and eaab.period_code <= #{param.periodCodeEnd}
and eaab.org_id = #{param.orgId}
and eaab.org_id in
#{item}
and eaab.account_code >= #{param.accountCodeStart}
and eaab.account_code <= #{param.accountCodeEnd}
and eaab.currency_code = #{param.currencyCode}
) ,exceptFiltered as ( SELECT id ,org_id ,account_code,currency_code, month_debit_amount,month_credit_amount,year_begin_debit_balance,year_begin_credit_balance, year_debit_amount,year_credit_amount,month_begin_debit_balance,month_begin_credit_balance, month_end_debit_balance, month_end_credit_balance FROM ( SELECT id ,org_id ,account_code,currency_code ,month_debit_amount,month_credit_amount,year_begin_debit_balance,year_begin_credit_balance ,year_debit_amount,year_credit_amount,month_begin_debit_balance,month_begin_credit_balance ,month_end_debit_balance,month_end_credit_balance,
COUNT(*) FILTER (WHERE month_debit_amount !=0 or month_credit_amount !=0) OVER (PARTITION BY org_id ,account_code,currency_code) AS cond1,
COUNT(*) FILTER (WHERE month_debit_amount !=0 or month_credit_amount !=0 or month_end_debit_balance!=0 or month_end_credit_balance!=0) OVER (PARTITION BY org_id ,account_code,currency_code) AS cond2,
COUNT(*) FILTER (WHERE month_end_debit_balance!=0 or month_end_credit_balance!=0) OVER (PARTITION BY org_id ,account_code,currency_code) AS cond3,
COUNT(*) FILTER (WHERE year_debit_amount !=0 or year_credit_amount !=0 ) OVER (PARTITION BY org_id ,account_code,currency_code) AS cond4,
COUNT(*) FILTER (WHERE month_end_debit_balance!=0 or month_end_credit_balance!=0 or year_debit_amount !=0 or year_credit_amount !=0 ) OVER (PARTITION BY org_id ,account_code,currency_code) AS cond5,
COUNT(*) OVER (PARTITION BY org_id ,account_code,currency_code) AS cond0,
COUNT(*) OVER (PARTITION BY org_id ,account_code,currency_code) AS total_rows FROM origin ) subquery WHERE 1=1
and cond1 = total_rows
and cond2 = total_rows
and cond3 = total_rows
and cond4 = total_rows
and cond5 = total_rows
and cond0 = total_rows
) , sub_account as ( select org_id ,account_code,min(id) min_id,max(id) max_id,currency_code from exceptFiltered group by org_id ,account_code ,currency_code ) ,sumtab as( select eaab.org_id ,eaab.account_code ,eaab.currency_code, sum(eaab.month_debit_amount) month_debit_amount, sum(eaab.month_credit_amount) month_credit_amount from origin eaab where 1=1 -- join sub_account on -- eaab.org_id = sub_account.org_id and eaab.account_code = sub_account.account_code and eaab.currency_code = sub_account.currency_code -- and eaab.id >= sub_account.min_id and eaab.id <= sub_account.max_id -- group by eaab.org_id ,eaab.account_code,eaab.currency_code and exists (select 1 from sub_account where eaab.org_id = sub_account.org_id and eaab.account_code = sub_account.account_code and eaab.currency_code = sub_account.currency_code and eaab.id between sub_account.min_id and sub_account.max_id) group by eaab.org_id ,eaab.account_code,eaab.currency_code ) ,mintab as( select eaab.org_id ,eaab.account_code, eaab.currency_code,eaab.year_begin_debit_balance,eaab.year_begin_credit_balance, eaab.year_debit_amount,eaab.year_credit_amount,eaab.month_begin_debit_balance, eaab.month_begin_credit_balance from origin eaab join sub_account on eaab.org_id = sub_account.org_id and eaab.account_code = sub_account.account_code and eaab.currency_code = sub_account.currency_code and eaab.id =sub_account.min_id ) ,maxtab as( select eaab.org_id ,eaab.account_code, eaab.currency_code,eaab.year_begin_debit_balance,eaab.year_begin_credit_balance, eaab.year_debit_amount,eaab.year_credit_amount,eaab.month_end_debit_balance, eaab.month_end_credit_balance from origin eaab join sub_account on eaab.org_id = sub_account.org_id and eaab.account_code = sub_account.account_code and eaab.currency_code = sub_account.currency_code and eaab.id =sub_account.max_id ) ,res_account as ( select sumtab.org_id ,sumtab.account_code,sumtab.currency_code,mintab.month_begin_debit_balance, mintab.month_begin_credit_balance, sumtab.month_debit_amount,sumtab.month_credit_amount,mintab.year_begin_debit_balance, mintab.year_begin_credit_balance,maxtab.year_debit_amount,maxtab.year_credit_amount,maxtab.month_end_debit_balance,maxtab.month_end_credit_balance from sumtab join mintab on sumtab.org_id = mintab.org_id and sumtab.account_code = mintab.account_code and sumtab.currency_code = mintab.currency_code join maxtab on sumtab.org_id = maxtab.org_id and sumtab.account_code = maxtab.account_code and sumtab.currency_code = maxtab.currency_code) --eg_voucher ,ev_eve as ( select ev.id voucher_id ,ev.org_id ,eve.account_code,eve.id,ev.currency,eve.debit_amount,eve.credit_amount from eg_voucher ev join eg_voucher_entry eve on ev.id = eve.voucher_id where 1=1
and ev.period_code =#{param.periodCodeEnd} and eve.period_code =#{param.periodCodeEnd}
and ev.org_id = #{param.orgId}
and ev.org_id in
#{item}
and eve.account_code >= #{param.accountCodeStart}
and eve.account_code <= #{param.accountCodeEnd}
and eve.currency = #{param.currencyCode}
) ,sub_ev as ( select string_agg(ev_eve.voucher_id::text, ',') voucher_id ,ev_eve.org_id ,ev_eve.account_code,ev_eve.currency,min(ev_eve.id) min_id,max(ev_eve.id) max_id from ev_eve group by ev_eve.org_id ,ev_eve.account_code,ev_eve.currency ) ,res_voucher as( select ev_eve.org_id ,ev_eve.account_code,ev_eve.currency currency_code, sum(ev_eve.debit_amount) debit_amount, sum(ev_eve.credit_amount) credit_amount from ev_eve join sub_ev on ev_eve.org_id = sub_ev.org_id and ev_eve.account_code = sub_ev.account_code and ev_eve.currency = sub_ev.currency and ev_eve.id >= sub_ev.min_id and ev_eve.id <= sub_ev.max_id group by ev_eve.org_id ,ev_eve.account_code,ev_eve.currency) --eg_manual ,em_emv as ( select em.org_id ,emv.account_code,em.currency_code,emv.id,emv.debit_amount,emv.credit_amount,em.period_code from eg_manual em join eg_manual_voucher emv on em.id = emv.manual_id where 1=1
and em.period_code =#{param.periodCodeEnd} and emv.period_code =#{param.periodCodeEnd}
and em.org_id = #{param.orgId}
and em.org_id in
#{item}
and emv.account_code >= #{param.accountCodeStart}
and emv.account_code <= #{param.accountCodeEnd}
and emv.currency_code = #{param.currencyCode}
) ,sub_em as ( select em_emv.org_id ,em_emv.account_code,em_emv.currency_code,min(em_emv.id) min_id,max(em_emv.id) max_id from em_emv group by em_emv.org_id ,em_emv.account_code,em_emv.currency_code ) ,res_manual as( select em_emv.org_id ,em_emv.account_code,em_emv.currency_code, sum(em_emv.debit_amount) debit_amount, sum(em_emv.credit_amount) credit_amount from em_emv join sub_em on em_emv.org_id = sub_em.org_id and em_emv.account_code = sub_em.account_code and em_emv.currency_code = sub_em.currency_code and em_emv.id >= sub_em.min_id and em_emv.id <= sub_em.max_id group by em_emv.org_id ,em_emv.account_code,em_emv.currency_code) ,res_all as( select
res_account.currency_code, --币种 res_account.org_id, --签约主体 res_account.account_code, --科目代码
