t_code ,sumtab.org_id ,sumtab.account_code ,sumtab.bill_contract_code,sumtab.currency_code, -- COALESCE(mintab.month_begin_debit_balance,0) month_begin_debit_balance, COALESCE(mintab.month_begin_credit_balance,0) month_begin_credit_balance, -- COALESCE(sumtab.month_debit_amount,0) month_debit_amount,COALESCE(sumtab.month_credit_amount,0) month_credit_amount, -- COALESCE(maxtab.year_begin_debit_balance,0) year_begin_debit_balance, COALESCE(maxtab.year_begin_credit_balance,0) year_begin_credit_balance, -- COALESCE(maxtab.year_debit_amount,0) year_debit_amount,COALESCE(maxtab.year_credit_amount,0) year_credit_amount, -- COALESCE(maxtab.month_end_debit_balance,0) month_end_debit_balance,COALESCE(maxtab.month_end_credit_balance,0) month_end_credit_balance case when account.debit_credit_type = 'DR' then COALESCE(mintab.month_begin_debit_balance,0) - COALESCE(mintab.month_begin_credit_balance,0) else 0 end as month_begin_debit_balance, case when account.debit_credit_type = 'CR' then COALESCE(mintab.month_begin_credit_balance,0) - COALESCE(mintab.month_begin_debit_balance,0) else 0 end as month_begin_credit_balance, --COALESCE(mintab.month_begin_debit_balance,0) month_begin_debit_balance, COALESCE(mintab.month_begin_credit_balance,0) month_begin_credit_balance, COALESCE(sumtab.month_debit_amount,0) month_debit_amount,COALESCE(sumtab.month_credit_amount,0) month_credit_amount, case when account.debit_credit_type = 'DR' then COALESCE(maxtab.year_begin_debit_balance,0) - COALESCE(maxtab.year_begin_credit_balance,0) else 0 end as year_begin_debit_balance, case when account.debit_credit_type = 'CR' then COALESCE(maxtab.year_begin_credit_balance,0) - COALESCE(maxtab.year_begin_debit_balance,0) else 0 end as year_begin_credit_balance, --COALESCE(maxtab.year_begin_debit_balance,0) year_begin_debit_balance, COALESCE(maxtab.year_begin_credit_balance,0) year_begin_credit_balance, COALESCE(maxtab.year_debit_amount,0) year_debit_amount,COALESCE(maxtab.year_credit_amount,0) year_credit_amount, case when account.debit_credit_type = 'DR' then COALESCE(maxtab.month_end_debit_balance,0) - COALESCE(maxtab.month_end_credit_balance,0) else 0 end as month_end_debit_balance, case when account.debit_credit_type = 'CR' then COALESCE(maxtab.month_end_credit_balance,0) - COALESCE(maxtab.month_end_debit_balance,0) else 0 end as month_end_credit_balance --COALESCE(maxtab.month_end_debit_balance,0) month_end_debit_balance,COALESCE(maxtab.month_end_credit_balance,0) month_end_credit_balance
from sumtab join mintab on sumtab.contract_code = mintab.contract_code and sumtab.org_id = mintab.org_id and sumtab.account_code = mintab.account_code and COALESCE(sumtab.bill_contract_code,'') =COALESCE(mintab.bill_contract_code,'') and sumtab.currency_code = mintab.currency_code join maxtab on sumtab.contract_code = maxtab.contract_code and sumtab.org_id = maxtab.org_id and sumtab.account_code = maxtab.account_code and COALESCE(sumtab.bill_contract_code,'') =COALESCE(maxtab.bill_contract_code,'') and sumtab.currency_code = maxtab.currency_code join (select distinct account_code ,debit_credit_type from eg_account ea ) account on sumtab.account_code = account.account_code where 1=1
and (COALESCE(sumtab.month_debit_amount,0) !=0 or COALESCE(sumtab.month_credit_amount,0) !=0)
and (COALESCE(sumtab.month_debit_amount,0) !=0 or COALESCE(sumtab.month_credit_amount,0) !=0 or COALESCE(maxtab.month_end_debit_balance,0)!=0 or COALESCE(maxtab.month_end_credit_balance,0)!=0)
and (COALESCE(maxtab.month_end_debit_balance,0)!=0 or COALESCE(maxtab.month_end_credit_balance,0)!=0)
and (COALESCE(maxtab.year_debit_amount,0) !=0 or COALESCE(maxtab.year_credit_amount,0) !=0 )
and (COALESCE(maxtab.month_end_debit_balance,0)!=0 or COALESCE(maxtab.month_end_credit_balance,0)!=0 or COALESCE(maxtab.year_debit_amount,0) !=0 or COALESCE(maxtab.year_credit_amount,0) !=0 )
)

        --eg_manual
        , em_emv as (
        select emv.contract_code ,em.org_id ,emv.account_code, emv.loans_contract_code,em.currency_code,emv.id,emv.debit_amount,emv.credit_amount,em.period_code  from eg_manual em join eg_manual_voucher emv on em.id = emv.manual_id
        where 1=1



        and em.period_code = emv.period_code



                and em.period_code >= #{param.otherPeriodCodeStart} and emv.period_code >= #{param.otherPeriodCodeStart}


                and 1=2




                and em.period_code <= #{param.otherPeriodCodeEnd} and emv.period_code <= #{param.otherPeriodCodeEnd}


                and 1=2




            and emv.contract_code in

                #{item}




            and em.org_id in

                #{item}



        and exists (select 1 from eg_account ea where ea.del_flag = '0' and emv.account_code= ea.account_code

            and ea.account_code >= #{param.accountCodeStart}


            and ea.account_code <= #{param.accountCodeEnd}


            and ea.account_name in

                #{item}


        )


            and em.currency_code in

                #{item}




            and emv.loans_contract_code in

                #{item}




            and em.process_status in

                #{item}


        and em.process_status = '1'
        )
        ,sub_em as (
        select em_emv.contract_code ,em_emv.org_id ,em_emv.account_code, em_emv.loans_contract_code,em_emv.currency_code,min(em_emv.id) min_id,max(em_emv.id) max_id from em_emv
        group by em_emv.contract_code ,em_emv.org_id ,em_emv.account_code ,em_emv.loans_contract_code,em_emv.currency_code
        )
        ,res_manual as(
        select em_emv.contract_code ,em_emv.org_id ,em_emv.account_code , em_emv.loans_contract_code bill_contract_code,em_emv.currency_code,
--                sum(em_emv.debit_amount) month_debit_amount, sum(em_emv.credit_amount) month_credit_amount
        0 as year_begin_debit_balance, 0 as year_begin_credit_balance,
        case when account.debit_credit_type = 'DR' then sum(em_emv.debit_amount) - sum(em_emv.credit_amount)
        else 0 end as year_debit_amount,
        case when account.debit_credit_type = 'CR' then sum(em_emv.credit_amount) - sum(em_emv.debit_amount)
        else 0 end as year_credit_amount,
        0 as month_begin_debit_balance, 0 as month_begin_credit_balance,
        case when account.debit_credit_type = 'DR' then sum(em_emv.debit_amount) - sum(em_emv.credit_amount)
        else 0 end as month_debit_amount,
        case when account.debit_credit_type = 'CR' then sum(em_emv.credit_amount) - sum(em_emv.debit_amount)
        else 0 end as month_credit_amount,
        case when account.debit_credit_type = 'DR' then sum(em_emv.debit_amount) - sum(em_emv.credit_amount)
        else 0 end as month_end_debit_balance,
        case when account.debit_credit_type = 'CR' then sum(em_emv.credit_amount) - sum(em_emv.debit_amount)
        else 0 end as month_end_credit_balance
        from em_emv join sub_em on em_emv.contract_code = sub_em.contract_code
        and em_emv.org_id = sub_em.org_id and em_emv.account_code = sub_em.account_code and COALESCE(em_emv.loans_contract_code,'') =COALESCE(sub_em.loans_contract_code,'') and em_emv.currency_code = sub_em.currency_code
        and em_emv.id >= sub_em.min_id and em_emv.id <= sub_em.max_id
        join (select distinct account_code ,debit_credit_type from eg_account ea ) account on em_emv.account_code = account.account_code
        group by em_emv.contract_code ,em_emv.org_id ,em_emv.account_code ,em_emv.loans_contract_code,em_emv.currency_code,account.debit_credit_type)

