ledger as ( select v.period_code, v.org_id, coalesce(nullif(v.currency, ''), 'RMB') currency_code, e.account_code, e.account_name, nullif(e.contract_code, '') contract_code, e.contract_name, e.client_code, e.client_name, nullif(e.bill_contract_code, '') bill_contract_code, coalesce(e.debit_amount, 0) debit_amount, coalesce(e.credit_amount, 0) credit_amount from eg_voucher v join eg_voucher_entry e on e.voucher_id = v.id and e.period_code = v.period_code where coalesce(v.del_flag, '0') = '0' and coalesce(e.del_flag, '0') = '0' and e.account_code is not null and e.account_code != '' and v.period_code <= #{param.periodCodeEnd}
and v.org_id in #{item}
and v.currency in #{item}
and e.account_code >= #{param.accountCodeStart}
and e.account_code <= #{param.accountCodeEnd}
and v.voucher_status in #{item}
and e.contract_code in #{item}
and e.bill_contract_code in #{item}
