and m.org_id in #{item}
and m.currency_code in #{item}
and mv.account_code >= #{param.accountCodeStart}
and mv.account_code <= #{param.accountCodeEnd}
and m.process_status in #{item}
and mv.contract_code in #{item}
and mv.loans_contract_code in #{item}
)

